Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $Root ".orcaly-backups\affiliate-program-$Timestamp"
$TempRoot = Join-Path $env:TEMP "orcaly-affiliate-program-$Timestamp"
$ZipPath = Join-Path $env:TEMP "orcaly-affiliate-program-$Timestamp.zip"
$MigrationDirectory = Join-Path $Root "supabase\migrations"
$MigrationMarker = "ORCALY_AFFILIATE_PROGRAM_DATABASE_V1"
$MigrationPath = ""
$MigrationCreated = $false

$PayloadBase64 = @'

'@

$PatchTargets = @(
    "app/page.tsx",
    "app/cadastro/page.tsx",
    "app/api/checkout/lead/route.ts",
    "app/api/leads/complete-account/route.ts",
    "lib/subscription-service.ts",
    "lib/subscription-checkout-payment.ts",
    "app/api/mercado-pago/webhook/route.ts",
    "app/api/webhooks/asaas/route.ts",
    "proxy.ts"
)

$PayloadTargets = @(
    "lib/affiliates/server.ts",
    "app/api/parceiros/register/route.ts",
    "app/api/parceiros/route.ts",
    "app/api/parceiros/track/route.ts",
    "app/api/admin/affiliates/route.ts",
    "app/parceiros/page.tsx",
    "app/parceiros/login/page.tsx",
    "app/parceiros/cadastro/page.tsx",
    "app/parceiros/termos/page.tsx",
    "app/parceiros/painel/page.tsx",
    "app/admin/indicacoes/page.tsx"
)

$OriginallyMissing = New-Object System.Collections.Generic.List[string]

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 76) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 76) -ForegroundColor DarkCyan
}

function Native-Path([string]$Relative) {
    return Join-Path $Root ($Relative -replace "/", "\")
}

function Backup-File([string]$Relative) {
    $Source = Native-Path $Relative

    if (-not (Test-Path -LiteralPath $Source)) {
        $OriginallyMissing.Add($Relative)
        return
    }

    $Backup = Join-Path $BackupRoot ($Relative -replace "/", "\")
    $Parent = Split-Path -Parent $Backup

    New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Backup -Force
}

function Restore-All {
    Write-Host "[AVISO] Restaurando os arquivos anteriores..." -ForegroundColor Yellow

    foreach ($Relative in @($PatchTargets + $PayloadTargets)) {
        $Backup = Join-Path $BackupRoot ($Relative -replace "/", "\")
        $Target = Native-Path $Relative

        if (Test-Path -LiteralPath $Backup) {
            $Parent = Split-Path -Parent $Target
            New-Item -ItemType Directory -Path $Parent -Force | Out-Null
            Copy-Item -LiteralPath $Backup -Destination $Target -Force
        }
        elseif ($OriginallyMissing.Contains($Relative)) {
            Remove-Item -LiteralPath $Target -Force -ErrorAction SilentlyContinue
        }
    }

    if (
        $MigrationCreated -and
        $MigrationPath -and
        (Test-Path -LiteralPath $MigrationPath)
    ) {
        Remove-Item -LiteralPath $MigrationPath -Force -ErrorAction SilentlyContinue
    }
}

function Get-FileText([string]$Relative) {
    $Path = Native-Path $Relative
    if (-not (Test-Path -LiteralPath $Path)) { return "" }
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Find-ExistingMigration {
    if (-not (Test-Path -LiteralPath $MigrationDirectory)) {
        return $null
    }

    return Get-ChildItem -LiteralPath $MigrationDirectory -Filter "*.sql" -File |
        Where-Object {
            $Content = [System.IO.File]::ReadAllText(
                $_.FullName,
                [System.Text.Encoding]::UTF8
            )
            $Content.Contains($MigrationMarker)
        } |
        Select-Object -First 1
}

Write-Section "ORCALY - PROGRAMA DE PARCEIROS 60%"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

git rev-parse --is-inside-work-tree | Out-Null
if ($LASTEXITCODE -ne 0) {
    throw "A pasta atual não é um repositório Git."
}

foreach ($Relative in $PatchTargets) {
    if (-not (Test-Path -LiteralPath (Native-Path $Relative))) {
        throw "Arquivo necessário não encontrado: $Relative"
    }
}

New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
New-Item -ItemType Directory -Path $TempRoot -Force | Out-Null

foreach ($Relative in @($PatchTargets + $PayloadTargets)) {
    Backup-File $Relative
}

Write-Host "[OK] Backup: $BackupRoot" -ForegroundColor Green

try {
    Write-Section "EXTRAINDO O PACOTE"

    $CleanPayload = $PayloadBase64 -replace "\s", ""
    [System.IO.File]::WriteAllBytes(
        $ZipPath,
        [Convert]::FromBase64String($CleanPayload)
    )

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($ZipPath, $TempRoot)

    Write-Host "[OK] Pacote extraído" -ForegroundColor Green

    Write-Section "CRIANDO A MIGRAÇÃO LOCAL"

    New-Item -ItemType Directory -Path $MigrationDirectory -Force | Out-Null
    $ExistingMigration = Find-ExistingMigration

    if ($ExistingMigration) {
        $MigrationPath = $ExistingMigration.FullName
        Write-Host "[OK] Migração existente: $MigrationPath" -ForegroundColor Green
    }
    else {
        $MigrationPath = Join-Path `
            $MigrationDirectory `
            ((Get-Date -Format "yyyyMMddHHmmss") + "_affiliate_program_sixty_percent.sql")

        Copy-Item `
            -LiteralPath (Join-Path $TempRoot "supabase\migrations\affiliate_program_sixty_percent.sql") `
            -Destination $MigrationPath `
            -Force

        $MigrationCreated = $true
        Write-Host "[OK] Migração criada: $MigrationPath" -ForegroundColor Green
    }

    Write-Section "INSTALANDO O PORTAL"

    foreach ($Relative in $PayloadTargets) {
        $Source = Join-Path $TempRoot ($Relative -replace "/", "\")
        $Target = Native-Path $Relative
        $Parent = Split-Path -Parent $Target

        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
        Copy-Item -LiteralPath $Source -Destination $Target -Force
        Write-Host "[OK] $Relative" -ForegroundColor Green
    }

    Write-Section "INTEGRANDO HOME, CADASTRO E PAGAMENTOS"

    node (Join-Path $TempRoot "patcher.mjs") $Root
    if ($LASTEXITCODE -ne 0) {
        throw "O patch de integração falhou."
    }

    Write-Section "VALIDANDO A IMPLEMENTAÇÃO"

    $Checks = @{
        "lib/affiliates/server.ts" = @(
            "ORCALY_AFFILIATE_PROGRAM_V1",
            "createAffiliateCommissionForApprovedPayment",
            "reverseAffiliateCommissionForPayment",
            "create_affiliate_payout_admin",
            "encryptPaymentCredential",
            "AsaasProvider"
        )
        "app/parceiros/painel/page.tsx" = @(
            "ORCALY_AFFILIATE_PROGRAM_V1",
            "Comissão futura",
            "request_payout",
            "Ranking de parceiros"
        )
        "app/admin/indicacoes/page.tsx" = @(
            "ORCALY_AFFILIATE_PROGRAM_V1",
            "Programa de Indicações",
            "send_payout",
            "reverse_commission"
        )
        "app/cadastro/page.tsx" = @(
            "ORCALY_AFFILIATE_INTEGRATION_V1",
            "referralCode",
            "/api/parceiros/track"
        )
        "lib/subscription-service.ts" = @(
            "ORCALY_AFFILIATE_INTEGRATION_V1",
            "createAffiliateCommissionForApprovedPayment"
        )
        "app/api/mercado-pago/webhook/route.ts" = @(
            "ORCALY_AFFILIATE_INTEGRATION_V1",
            "reverseAffiliateCommissionForPayment"
        )
        "app/api/webhooks/asaas/route.ts" = @(
            "ORCALY_AFFILIATE_INTEGRATION_V1",
            "updateAffiliatePayoutFromTransferEvent"
        )
        "proxy.ts" = @(
            "ORCALY_AFFILIATE_INTEGRATION_V1",
            "affiliateSensitivePage",
            "/parceiros/login"
        )
    }

    foreach ($Relative in $Checks.Keys) {
        $Content = Get-FileText $Relative

        foreach ($Marker in $Checks[$Relative]) {
            if (-not $Content.Contains($Marker)) {
                throw "Marcador ausente em ${Relative}: $Marker"
            }
        }

        Write-Host "[OK] $Relative" -ForegroundColor Green
    }

    $MigrationContent = [System.IO.File]::ReadAllText(
        $MigrationPath,
        [System.Text.Encoding]::UTF8
    )

    if (-not $MigrationContent.Contains($MigrationMarker)) {
        throw "O marcador da migração local está ausente."
    }

    Write-Section "VALIDANDO DIFF"

    git --no-pager diff --check
    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content -LiteralPath (Join-Path $Root "package.json") -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"
        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "PROGRAMA DE PARCEIROS IMPLEMENTADO"

    Write-Host "Comissão: 60% do primeiro pagamento elegível"
    Write-Host "Teste gratuito mínimo: 7 dias"
    Write-Host "Retenção: 14 dias"
    Write-Host "Pagamento mínimo: R$ 50,00"
    Write-Host "Atribuição: 60 dias"
    Write-Host "Portal: /parceiros"
    Write-Host "Login parceiro: /parceiros/login"
    Write-Host "Dashboard parceiro: /parceiros/painel"
    Write-Host "Admin: /admin/indicacoes"
    Write-Host "Pix: criptografado e sujeito a verificação"
    Write-Host "Estorno: reversão automática e ajuste futuro"
    Write-Host "Banco de produção: já atualizado"
    Write-Host "Migração local: $MigrationPath"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host ""
    Write-Host "O envio automático usa o Asaas de produção somente após aprovação administrativa do lote." -ForegroundColor Cyan
}
catch {
    Restore-All
    throw
}
finally {
    Remove-Item -LiteralPath $TempRoot -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $ZipPath -Force -ErrorAction SilentlyContinue
}
